import io, contextlib, roman

assert to_roman := roman.to_roman
cases = {1:"I",3:"III",4:"IV",9:"IX",14:"XIV",40:"XL",90:"XC",400:"CD",
         1994:"MCMXCIV",2026:"MMXXVI",3999:"MMMCMXCIX"}
for n, exp in cases.items():
    assert to_roman(n) == exp, (n, to_roman(n))

def decode(s):
    vals = {"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}
    total = 0
    for i, ch in enumerate(s):
        v = vals[ch]
        total += -v if i+1 < len(s) and vals[s[i+1]] > v else v
    return total
for n in range(1, 4000):
    assert decode(to_roman(n)) == n, n

for bad in (0, -1, 4000):
    try:
        to_roman(bad); raise AssertionError(bad)
    except ValueError: pass
for bad in ("5", 5.0, True):
    try:
        to_roman(bad); raise AssertionError(bad)
    except TypeError: pass

public = [name for name in dir(roman) if not name.startswith("_")]
assert public == ["to_roman"], public

buf_out, buf_err = io.StringIO(), io.StringIO()
with contextlib.redirect_stdout(buf_out), contextlib.redirect_stderr(buf_err):
    import importlib; importlib.reload(roman)
assert buf_out.getvalue() == "" and buf_err.getvalue() == ""
print("ALL CHECKS PASSED")
